def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = STATEMENT_CUT_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Retrieves configuration parameters for the statement cut feature.

    Args:
        vault: The SmartContractVault instance to query.
        param_fetcher_id: The unique identifier for the parameter fetcher.

    Returns:
        Parameters for the statement cut feature.
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def _append_to_state(
    state: state_utils.SmartContractState,
    balance_fetcher_id: str = common_fetchers.EFFECTIVE_DATE_BOF_ID,
    param_fetcher_id: str = STATEMENT_CUT_POF_ID,
) -> state_utils.SmartContractState:
    """Updates the contract state with live balances and specific parameter observations."""
    return state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, param_fetcher_id),
        balances=state.vault.get_balances_observation(fetcher_id=balance_fetcher_id).balances,
    )


def get_scheduled_events(
    state: state_utils.SmartContractState,
    fetchers_config: StatementCutFetchersConfig = DEFAULT_STATEMENT_CUT_FETCHERS_CONFIG,
) -> dict[str, ScheduledEvent]:
    """Get scheduled event for monthly statement cut.

    Args:
        state: The current state of the smart contract.
        fetchers_config: Configuration for the fetchers.

    Returns:
        The scheduled events for the statement cut.
    """
    state = state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, fetchers_config.param_fetcher_id),
    )

    schedule_param_ids = {
        STATEMENT_DAY_PARAM.id,
        STATEMENT_TIME_PARAM.id,
    }

    rejection = state_utils.check_parameters_exist(state=state, param_ids=schedule_param_ids)
    assert rejection is None, rejection

    statement_time_str: str = state.parameters[STATEMENT_TIME_PARAM.id]  # type: ignore
    statement_time: date_and_time.Time = date_and_time.parse_time_str(statement_time_str)

    day = int(state.parameters[STATEMENT_DAY_PARAM.id])  # type: ignore

    return {
        STATEMENT_CUT_EVENT: ScheduledEvent(
            start_datetime=state.effective_datetime.astimezone(state.vault.events_timezone),
            expression=ScheduleExpression(
                day=day,
                hour=statement_time.hour,
                minute=statement_time.minute,
                second=statement_time.second,
            ),
        )
    }


def _get_balance_at_address(balances: Mapping, address: str, denomination: str) -> Decimal:
    """Gets the net balance at a specific address."""
    return balances[(address, DEFAULT_ASSET, denomination, Phase.COMMITTED)].net


def _calculate_total_balance(balances: Mapping, denomination: str) -> Decimal:
    """Calculates total outstanding balance across all relevant addresses."""
    addresses = [
        apex_addresses.PURCHASE,
        apex_addresses.CASH_ADVANCE,
        apex_addresses.INTEREST_CHARGED,
        apex_addresses.FEES,
    ]
    total = Decimal(0)
    for address in addresses:
        total += _get_balance_at_address(balances, address, denomination)
    return total


def _apply_accrued_interest(
    state: state_utils.SmartContractState,
    denomination: str,
    interest_receivable_account: str,
) -> list[CustomInstruction]:
    """At statement cut, apply (capitalise) any accrued interest.

    Moves interest from the accrued interest addresses to the INTEREST_CHARGED address.

    Args:
        state: The current state of the smart contract.
        denomination: The account denomination.
        interest_receivable_account: The internal account for interest receivable.

    Returns:
        List of custom instructions for the interest application.
    """
    instructions: list[CustomInstruction] = []

    for accrual_address in [
        apex_addresses.INTEREST_ACCRUED_PURCHASE,
        apex_addresses.INTEREST_ACCRUED_CASH_ADVANCE,
    ]:
        accrued_amount = _get_balance_at_address(state.balances, accrual_address, denomination)

        if accrued_amount > 0:
            rounded_amount = accrued_amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

            instructions.extend(
                accrual_utils.create_receivable_accrual_application_custom_instruction(
                    customer_account=state.vault.account_id,
                    denomination=denomination,
                    application_amount=rounded_amount,
                    accrual_amount=accrued_amount,
                    instruction_details=posting_utils.standard_instruction_details(
                        description=f"Interest application from {accrual_address}: "
                        f"{rounded_amount}",
                        event_type=STATEMENT_CUT_EVENT,
                        gl_impacted=True,
                    ),
                    accrual_customer_address=accrual_address,
                    accrual_internal_account=interest_receivable_account,
                    application_customer_address=apex_addresses.INTEREST_CHARGED,
                    application_internal_account=interest_receivable_account,
                )
            )

    return instructions


def calculate_minimum_payment(
    total_balance: Decimal,
    accrued_interest: Decimal,
    fees: Decimal,
    percentage: Decimal,
    fixed_amount: Decimal,
) -> Decimal:
    """Calculates the minimum payment due.

    The minimum payment is: max(total_balance * percentage, fixed_minimum, accrued_interest + fees)
    Capped at the total outstanding balance.

    Args:
        total_balance: The total outstanding balance.
        accrued_interest: Total accrued interest being applied.
        fees: Total outstanding fees.
        percentage: Minimum payment percentage (e.g. 0.02 for 2%).
        fixed_amount: Fixed minimum payment amount (e.g. 25).

    Returns:
        The minimum payment amount.
    """
    if total_balance <= 0:
        return Decimal(0)

    percentage_amount = (total_balance * percentage).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )
    interest_plus_fees = accrued_interest + fees

    minimum = max(percentage_amount, fixed_amount, interest_plus_fees)

    # Cap at total balance
    return min(minimum, total_balance)


def _create_tracker_posting(
    account_id: str,
    address: str,
    amount: Decimal,
    denomination: str,
    description: str,
) -> CustomInstruction:
    """Creates a posting to update a tracker address (internal memo posting).

    For tracker addresses on ASSET tside accounts, we debit the tracker address
    and credit DEFAULT to record the tracked amount.

    Args:
        account_id: The customer account ID.
        address: The tracker address.
        amount: The amount to track.
        denomination: The account denomination.
        description: Description for instruction details.

    Returns:
        A CustomInstruction for the tracker posting.
    """
    return CustomInstruction(
        postings=posting_utils.create_postings(
            amount=amount,
            debit_account=account_id,
            debit_address=address,
            credit_account=account_id,
            credit_address=DEFAULT_ADDRESS,
            denomination=denomination,
        ),
        instruction_details=posting_utils.standard_instruction_details(
            description=description,
            event_type=STATEMENT_CUT_EVENT,
            gl_impacted=False,
        ),
        override_all_restrictions=True,
    )


def statement_cut_logic(
    state: state_utils.SmartContractState,
    account_type: str = "",
    fetchers_config: StatementCutFetchersConfig = DEFAULT_STATEMENT_CUT_FETCHERS_CONFIG,
) -> list[CustomInstruction]:
    """Performs statement cut logic.

    1. Apply accrued interest (capitalise to INTEREST_CHARGED)
    2. Calculate minimum payment due
    3. Record minimum payment due in tracker
    4. Record statement balance in tracker
    5. Reset total repayments tracker

    Args:
        state: The current state of the smart contract.
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for the statement cut.
    """
    state = _append_to_state(state=state, param_fetcher_id=fetchers_config.param_fetcher_id)

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            MINIMUM_PAYMENT_PERCENTAGE_PARAM.id,
            MINIMUM_PAYMENT_FIXED_AMOUNT_PARAM.id,
            INTEREST_RECEIVABLE_ACCOUNT_PARAM.id,
        },
    )
    assert rejection is None, rejection

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    percentage: Decimal = state.parameters[MINIMUM_PAYMENT_PERCENTAGE_PARAM.id]  # type: ignore
    fixed_amount: Decimal = state.parameters[MINIMUM_PAYMENT_FIXED_AMOUNT_PARAM.id]  # type: ignore
    interest_receivable_account: str = state.parameters[INTEREST_RECEIVABLE_ACCOUNT_PARAM.id]  # type: ignore

    instructions: list[CustomInstruction] = []

    # 1. Get total accrued interest before applying
    accrued_purchase = _get_balance_at_address(
        state.balances, apex_addresses.INTEREST_ACCRUED_PURCHASE, denomination
    )
    accrued_cash_advance = _get_balance_at_address(
        state.balances, apex_addresses.INTEREST_ACCRUED_CASH_ADVANCE, denomination
    )
    total_accrued = accrued_purchase + accrued_cash_advance

    # 2. Apply accrued interest
    interest_instructions = _apply_accrued_interest(
        state=state,
        denomination=denomination,
        interest_receivable_account=interest_receivable_account,
    )
    instructions.extend(interest_instructions)

    # 3. Calculate total balance (including the interest that's about to be applied)
    current_total = _calculate_total_balance(state.balances, denomination)
    fees_balance = _get_balance_at_address(state.balances, apex_addresses.FEES, denomination)
    # Add the accrued interest that will be capitalised
    total_balance_after_interest = current_total + total_accrued.quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )

    # 4. Calculate minimum payment
    min_payment = calculate_minimum_payment(
        total_balance=total_balance_after_interest,
        accrued_interest=total_accrued.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP),
        fees=fees_balance,
        percentage=percentage,
        fixed_amount=fixed_amount,
    )

    # 5. Record minimum payment due tracker
    if min_payment > 0:
        # Reset old tracker value first
        old_min_payment = _get_balance_at_address(
            state.balances, apex_addresses.MINIMUM_PAYMENT_DUE_TRACKER, denomination
        )
        if old_min_payment > 0:
            instructions.append(
                CustomInstruction(
                    postings=posting_utils.create_postings(
                        amount=old_min_payment,
                        debit_account=state.vault.account_id,
                        debit_address=DEFAULT_ADDRESS,
                        credit_account=state.vault.account_id,
                        credit_address=apex_addresses.MINIMUM_PAYMENT_DUE_TRACKER,
                        denomination=denomination,
                    ),
                    instruction_details=posting_utils.standard_instruction_details(
                        description="Reset minimum payment due tracker",
                        event_type=STATEMENT_CUT_EVENT,
                        gl_impacted=False,
                    ),
                    override_all_restrictions=True,
                )
            )

        instructions.append(
            _create_tracker_posting(
                account_id=state.vault.account_id,
                address=apex_addresses.MINIMUM_PAYMENT_DUE_TRACKER,
                amount=min_payment,
                denomination=denomination,
                description=f"Minimum payment due: {min_payment}",
            )
        )

    # 6. Record statement balance tracker
    old_statement_balance = _get_balance_at_address(
        state.balances, apex_addresses.STATEMENT_BALANCE_TRACKER, denomination
    )
    if old_statement_balance > 0:
        instructions.append(
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=old_statement_balance,
                    debit_account=state.vault.account_id,
                    debit_address=DEFAULT_ADDRESS,
                    credit_account=state.vault.account_id,
                    credit_address=apex_addresses.STATEMENT_BALANCE_TRACKER,
                    denomination=denomination,
                ),
                instruction_details=posting_utils.standard_instruction_details(
                    description="Reset statement balance tracker",
                    event_type=STATEMENT_CUT_EVENT,
                    gl_impacted=False,
                ),
                override_all_restrictions=True,
            )
        )

    if total_balance_after_interest > 0:
        instructions.append(
            _create_tracker_posting(
                account_id=state.vault.account_id,
                address=apex_addresses.STATEMENT_BALANCE_TRACKER,
                amount=total_balance_after_interest,
                denomination=denomination,
                description=f"Statement balance: {total_balance_after_interest}",
            )
        )

    # 7. Reset total repayments tracker
    old_repayments = _get_balance_at_address(
        state.balances, apex_addresses.TOTAL_REPAYMENTS_TRACKER, denomination
    )
    if old_repayments > 0:
        instructions.append(
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=old_repayments,
                    debit_account=state.vault.account_id,
                    debit_address=DEFAULT_ADDRESS,
                    credit_account=state.vault.account_id,
                    credit_address=apex_addresses.TOTAL_REPAYMENTS_TRACKER,
                    denomination=denomination,
                ),
                instruction_details=posting_utils.standard_instruction_details(
                    description="Reset total repayments tracker",
                    event_type=STATEMENT_CUT_EVENT,
                    gl_impacted=False,
                ),
                override_all_restrictions=True,
            )
        )

    return instructions
